export const MAP_W = 720;
export const MAP_H = 439;
const BOX = [-0.262, 51.448, 0.012, 51.552];

/** Map position of a point given in degrees. */
export function mapXY(lat: number, lon: number): [number, number] {
  return [((lon - BOX[0]) / (BOX[2] - BOX[0])) * MAP_W, ((BOX[3] - lat) / (BOX[3] - BOX[1])) * MAP_H];
}

